// GENERATED BY SYMPLRV3 — DO NOT EDIT
// Response-driven branching + list filters (mirrors @symplrv3/schema's
// matchOp/getPath — the designer evaluates the SAME logic in its preview).

export type RuleOp =
  | 'eq'
  | 'neq'
  | 'gt'
  | 'gte'
  | 'lt'
  | 'lte'
  | 'contains'
  | 'exists'
  | 'notExists';

export interface ResponseRule {
  source: 'status' | 'body';
  path?: string;
  op: RuleOp;
  value?: string | number | boolean;
  navigateTo: string;
  /** Api chain: binding id to execute when the rule matches. */
  callBindingId?: string;
  /** SDK chain: integration-action id to execute when the rule matches.
   * Chaining works across kinds (api→sdk, sdk→sdk, sdk→api). */
  callActionId?: string;
  /** Modal: id of a modal widget on the binding's screen to open on match. */
  openModalId?: string;
  alert?: { title: string; message?: string };
  /** Present when the rule REBUILDS the stack instead of pushing — see ruleNav.
   * '' makes the target the only entry; a name puts the target on top of it. */
  resetTo?: string;
}

export function matchOp(actual: unknown, op: RuleOp, value?: unknown): boolean {
  switch (op) {
    case 'exists':
      return actual !== undefined && actual !== null;
    case 'notExists':
      return actual === undefined || actual === null;
    case 'contains':
      return Array.isArray(actual)
        ? actual.some((x) => String(x) === String(value))
        : toStr(actual).includes(toStr(value));
    case 'eq':
      return String(actual) === String(value);
    case 'neq':
      return String(actual) !== String(value);
    default: {
      const a = Number(actual);
      const b = Number(value);
      if (Number.isNaN(a) || Number.isNaN(b)) return false;
      if (op === 'gt') return a > b;
      if (op === 'gte') return a >= b;
      if (op === 'lt') return a < b;
      return a <= b;
    }
  }
}

/** A value worth sending: present, not null, not an empty string. */
function holdsValue(v: unknown): boolean {
  return v !== undefined && v !== null && v !== '';
}

/**
 * `a ?? b` — the first path that holds a value. A bank profile carries either
 * a physical or a virtual card product code depending on the environment, and
 * the order must send whichever exists (reference useCardProductCode). No real
 * path contains " ?? ", so every existing path reads exactly as before.
 */
function firstAlternative(obj: unknown, path: string): unknown {
  for (const alt of path.split(' ?? ')) {
    const v = getPath(obj, alt.trim());
    if (holdsValue(v)) return v;
  }
  return undefined;
}

/**
 * `values[*].rest` — the first row where rest has a value. The bank profile
 * keeps each setting in its own record, so the product code is not always in
 * row 0 (reference parseProductCode scans every record).
 */
function firstRowValue(obj: unknown, path: string, star: number): unknown {
  const rows = getPath(obj, path.slice(0, star));
  if (!Array.isArray(rows)) return undefined;
  const rest = path.slice(star + 3).replace(/^\./, '');
  for (const row of rows) {
    const v = getPath(row, rest);
    if (holdsValue(v)) return v;
  }
  return undefined;
}

// `items[field=value]` picks the row whose field equals value — the twin of
// the compile-time accessSuffix (emit/api.ts). Without it this reader treats
// "[code=X]" as a plain key and returns undefined, so a path that resolves
// correctly in a responseBinding would resolve to nothing in a nav param.
const PATH_PRED = /^([^[]*)\[([A-Za-z_$][\w$]*)=(.*)\]$/;

/** One segment down from an object. */
function stepInto(cur: object, seg: string): unknown {
  const m = PATH_PRED.exec(seg);
  if (!m) return (cur as Record<string, unknown>)[seg];
  const [, key, field, want] = m;
  const arr: unknown = key ? (cur as Record<string, unknown>)[key] : cur;
  if (!Array.isArray(arr)) return undefined;
  return arr.find((r) => toStr((r as Record<string, unknown> | null)?.[field]) === want);
}

/*
 * The path forms live in the helpers above rather than inline: each form added
 * a loop and its guards to this one function, and three of them took it to a
 * cognitive complexity of 28 against Sonar's 15 (S3776) — in a module every
 * generated app ships.
 */
export function getPath(obj: unknown, path: string): unknown {
  if (!path) return obj;
  if (path.includes(' ?? ')) return firstAlternative(obj, path);
  const star = path.indexOf('[*]');
  if (star >= 0) return firstRowValue(obj, path, star);
  let cur: unknown = obj;
  for (const seg of path
    .replaceAll(/\[(\d+)\]/g, '.$1')
    .split('.')
    .filter(Boolean)) {
    if (cur === null || cur === undefined || typeof cur !== 'object') return undefined;
    cur = stepInto(cur, seg);
  }
  return cur;
}

/**
 * A bound response value being rendered as TEXT.
 *
 * getPath returns `unknown`, and `String(x ?? '')` on an object produces the
 * literal "[object Object]" on screen — which is what shipped whenever a
 * binding pointed one level too high (Sonar S6551 flags exactly this). An array
 * reads as a comma-separated list and an object as JSON: still not what the
 * design wanted, but debuggable instead of meaningless.
 */
export function toStr(v: unknown): string {
  if (v === null || v === undefined) return '';
  if (typeof v === 'string') return v;
  if (typeof v === 'number' || typeof v === 'boolean' || typeof v === 'bigint') return String(v);
  if (Array.isArray(v)) return v.map(toStr).join(', ');
  try {
    return JSON.stringify(v) ?? '';
  } catch {
    return ''; // circular structure — nothing sensible to render
  }
}

/** The selected position of a chip, tile or segmented group: the index the
 * control recorded when pressed, else where the stored label sits among the
 * options, else the design's default. One call instead of the nested ternary
 * every group used to inline (Sonar S3358). */
export function pickedIndex(
  recorded: unknown,
  options: readonly string[],
  label: unknown,
  fallback: number,
): number {
  if (typeof recorded === 'number') return recorded;
  return optionIndex(label, [options], fallback);
}

/** Where `value` sits in the first list that has it, else the fallback — a
 * route param may name an option by its label OR by the value it stands for. */
export function optionIndex(
  value: unknown,
  lists: readonly (readonly string[])[],
  fallback: number,
): number {
  const v = toStr(value);
  for (const list of lists) {
    const at = list.indexOf(v);
    if (at !== -1) return at;
  }
  return fallback;
}

/** A bound response value being used as a LIST (dropdown options, a list's
 * item array). Arrays pass through; null/undefined read as empty.
 *
 * A SCALAR becomes a one-element list instead of throwing. An authored binding
 * path can legitimately land on a single value where the design expects the
 * whole column — `data[0].walletId` reaches one wallet id, not the array of
 * them — and `.map()` on that string crashed the whole screen with
 * "…map is not a function". One option is a truthful rendering of one value;
 * a runtime TypeError is not. */
export function asList(v: unknown): any[] {
  if (Array.isArray(v)) return v;
  return v === null || v === undefined ? [] : [v];
}

/** Rows of n, for a bound GRID that cannot use a FlatList's numColumns — one
 * inside the page's own scroller, where a nested vertical VirtualizedList
 * breaks windowing and fights the page for the drag. The last row is short
 * when the data does not divide evenly, exactly as the static grid's chunking
 * leaves it. A column count below 1 would loop forever, so it is floored. */
export function chunk<T>(list: T[], n: number): T[][] {
  const size = Math.max(1, Math.floor(n));
  const out: T[][] = [];
  for (let i = 0; i < list.length; i += size) out.push(list.slice(i, i + size));
  return out;
}

/** A shown amount as a number: "$40" is 40, "1,299 kr" is 1299, 12.5 stays
 * 12.5. Commas are thousands separators, the same reading the importer used
 * to decide the design's total added up. Anything unreadable counts as 0, so
 * one bad row cannot blank the whole total. */
export function amountOf(v: unknown): number {
  if (typeof v === 'number') return Number.isFinite(v) ? v : 0;
  const n = Number(
    toStr(v)
      .replaceAll(',', '')
      .replaceAll(/[^0-9.-]/g, ''),
  );
  return Number.isFinite(n) ? n : 0;
}

/** A total printed the way the design printed its sample ("$" + 423). A
 * whole number keeps the design's decimals; a fractional one shows at least
 * two, because rounding money away is worse than an extra ".50". */
export function fmtTotal(n: number, prefix: string, suffix: string, decimals: number): string {
  const d = Number.isInteger(n) ? decimals : Math.max(decimals, 2);
  return prefix + n.toFixed(d) + suffix;
}

/** Truthiness of an API value bound to a checkbox/switch. JSON booleans pass
 * straight through; the string flags APIs really send ("false", "0", "N",
 * "no") would all be truthy under a plain Boolean(), so they are spelled out.
 * The designer preview mirrors this exactly. */
export function boolish(v: unknown): boolean {
  if (typeof v === 'string') {
    const s = v.trim().toLowerCase();
    return !(s === '' || s === 'false' || s === '0' || s === 'n' || s === 'no');
  }
  return Boolean(v);
}

/*
 * The four helpers below each replace an expression a screen used to spell out
 * at every site. Inline, each was a ternary or a branch counted against the
 * SCREEN's cognitive complexity (S3776) — once per bound switch, per gated
 * widget that keeps its space, per polled status — so a design with enough of
 * them failed the gate with nothing wrong in any one of them.
 */

/** A bound checked state, or the design's own when the response omits the
 * field (null / undefined) — never silently forced off. */
export function boolishOr(v: unknown, fallback: boolean): boolean {
  return v == null ? fallback : boolish(v);
}

/** A widget hidden WITHOUT giving up its space: invisible and untouchable
 * while `shown` is false, laid out the same either way. */
export function keptSpace(shown: unknown): {
  style: { opacity: number } | undefined;
  pointerEvents: 'box-none' | 'none';
} {
  return shown
    ? { style: undefined, pointerEvents: 'box-none' }
    : { style: { opacity: 0 }, pointerEvents: 'none' };
}

/** The value of the first arm whose condition holds, else null. Every
 * condition is a pure read of state already in hand, so evaluating them all
 * costs nothing and keeps the choice one flat list. */
export function firstWhen<T>(arms: ReadonlyArray<readonly [unknown, T]>): T | null {
  for (const [when, then] of arms) if (when) return then;
  return null;
}

/**
 * The status a polled read hands its response rules — or null while the poll
 * should keep waiting.
 *
 * `seen` counts the answers (a new data or error stamp is a new answer). A
 * read that succeeded without reaching one of `plan.done` waits, until
 * `plan.max` answers have come back, when it is reported as a time-out
 * (408); an error, or an answer that is done, is reported as it came.
 */
export function pollVerdict(
  q: { isSuccess: boolean; dataUpdatedAt: number; errorUpdatedAt: number },
  settledRead: { body: unknown; status: number },
  seen: { current: { n: number; at: string } },
  plan: { path: string; done: readonly string[]; max: number; notFoundPending?: boolean },
): number | null {
  const stamp = String(q.dataUpdatedAt) + ':' + String(q.errorUpdatedAt);
  if (stamp !== seen.current.at) seen.current = { n: seen.current.n + 1, at: stamp };
  const v =
    getPath(settledRead.body, plan.path) ??
    getPath((settledRead.body as { data?: unknown } | null)?.data, plan.path);
  const done = typeof v === 'string' && plan.done.includes(v);
  const waiting = q.isSuccess || (plan.notFoundPending === true && settledRead.status === 404);
  if (!waiting || done) return settledRead.status;
  return seen.current.n >= plan.max ? 408 : null;
}

/** Body and HTTP status of a settled query, whichever way it settled.
 * Response rules are matched against exactly this pair on every screen, and
 * spelling the ternaries out at each site is what pushed a busy screen past the
 * cognitive-complexity limit. */
export function settled(q: { isSuccess: boolean; data?: unknown; error?: unknown }): {
  body: unknown;
  status: number;
} {
  if (q.isSuccess) {
    // no assertion: data is already unknown here, unlike at the call sites
    // this replaced, where react-query had given it a concrete type
    return { body: q.data, status: resStatus(q.data) };
  }
  return {
    body: parseErrorBody(q.error),
    status: (q.error as { status?: number } | null)?.status ?? 0,
  };
}

/** Real HTTP status of a SUCCESS response: apiFetch stamps it on object
 * bodies as a non-enumerable __status (a 201/202/204 would otherwise be
 * indistinguishable from 200 once axios unwraps res.data). */
export function resStatus(body: unknown, fallback = 200): number {
  const st =
    body && typeof body === 'object' ? (body as { __status?: unknown }).__status : undefined;
  return typeof st === 'number' ? st : fallback;
}

/** Best-effort response body from a thrown error: AppError keeps the raw
 * HTTP body (a JSON string) on cause.body — parse it so body-path rules can
 * read fields of error responses too. */
export function parseErrorBody(err: unknown): unknown {
  const e = err as { cause?: { body?: unknown } | null; body?: unknown; message?: unknown } | null;
  const raw = e?.cause?.body ?? e?.body;
  if (typeof raw === 'string') {
    try {
      return JSON.parse(raw);
    } catch {
      return raw;
    }
  }
  return raw ?? e?.message;
}

/**
 * Land on a screen by REBUILDING the stack, not pushing onto it.
 *
 * A step that completes must not leave the screens that performed it behind:
 * after a sign-in hand-off returns, pushing the next step leaves the browser
 * and its waiting screen underneath, and Back walks the user into a finished
 * flow that re-fires a one-time code.
 *
 * resetTo names the screen the target sits ON TOP OF, so Back reaches a
 * sensible place instead of exiting; '' makes the target the only entry.
 */
export function ruleReset(
  navigation: { reset: (s: unknown) => void },
  target: string,
  resetTo: string | undefined,
  params?: unknown,
): void {
  const routes = resetTo
    ? [{ name: resetTo }, { name: target, params }]
    : [{ name: target, params }];
  if (__DEV__) console.log('[Test] rule.reset stack=' + routes.map((r) => r.name).join(' > '));
  navigation.reset({ index: routes.length - 1, routes });
}

/**
 * The value a rule is tested against.
 *
 * ENVELOPE TOLERANCE: many APIs wrap payloads as `{ data: {...} }`, so when the
 * path misses on the raw body it is retried against `body.data` — rule paths and
 * response-binding paths then accept the same spelling. Both readers below went
 * through their own copy of this; one of them is a rule match and the other is
 * the same rule's target, and they must never disagree about what "actual" is.
 */
function ruleActual(r: ResponseRule, body: unknown, status: number): unknown {
  if (r.source === 'status') return status;
  const direct = getPath(body, r.path ?? '');
  if (direct !== undefined) return direct;
  const envelope =
    body !== null && typeof body === 'object' && 'data' in (body as Record<string, unknown>)
      ? (body as Record<string, unknown>).data
      : undefined;
  return envelope === undefined ? undefined : getPath(envelope, r.path ?? '');
}

/** Did a matched rule take the response over? Then the caller's own success or
 * error handling must not also run — one response, one outcome. */
export function ruleHandled(rule: ResponseRule): boolean {
  return Boolean(
    rule.navigateTo || rule.callBindingId || rule.callActionId || rule.openModalId || rule.alert,
  );
}

/**
 * Everything about a rule's navigation that only the SCREEN knows.
 *
 * Passed as DATA and function references, never as an inline callback: the rule
 * handler that calls ruleNav is already two or three closures deep (a press, a
 * promise, a mutation callback), and one more arrow there is a fifth level of
 * nested functions — which is a finding of its own (S2004) and, worse, reads
 * like the tangle it replaced.
 */
export interface RuleNavPlan {
  method: 'navigate' | 'replace';
  /** Screen names that are FLOW OUTCOMES — a real screen only at runtime. */
  flows?: readonly string[];
  /** The screen's own resolveScreenFlow. Handed in rather than imported: this
   * module is the branching logic and must not depend on navigation. */
  resolveFlow?: (intended: string) => Promise<string>;
  /** goTo from ../navigation/tabs, when the app folds screens into a tab group
   * — it rewrites a tab member into its nested form. Absent otherwise. */
  goTo?: (
    navigation: unknown,
    method: 'navigate' | 'replace',
    name: string,
    params?: never,
  ) => void;
  /** goReset from ../navigation/tabs, present for the same reason goTo is.
   * A reset needs it for a second reason on top of folding tab members: the
   * reset must run on the ROOT navigator, and a screen inside the tabs holds
   * the tab navigator, which owns none of those routes. */
  goReset?: (navigation: unknown, routes: Array<{ name: string; params?: unknown }>) => void;
  params?: unknown;
}

function goRuleTarget(navigation: unknown, plan: RuleNavPlan, target: string): void {
  if (plan.goTo) plan.goTo(navigation, plan.method, target, plan.params as never);
  else
    (navigation as Record<string, (n: string, p?: unknown) => void>)[plan.method]?.(
      target,
      plan.params,
    );
}

/**
 * A matched rule's navigation: REBUILD the stack when it carries resetTo, push
 * otherwise. The decision is made at runtime, not at emit time — one rule list
 * mixes both kinds (a UAE PASS success resets onto the chooser while a rejection
 * on the same list just navigates).
 *
 * This used to be spelled out at every rule handler on every screen: the
 * navigateTo test, the resetTo test, its else, and the flow-outcome test inside
 * it. Four branches per binding, in the busiest function on the screen.
 */
export function ruleNav(
  rule: ResponseRule,
  navigation: { reset: (s: unknown) => void },
  plan: RuleNavPlan,
): void {
  const target = rule.navigateTo;
  if (!target) return;
  if (rule.resetTo !== undefined) {
    // In tabs mode goReset already folds a tab member into its group AND
    // walks up to the root navigator. Without it, naming a tab screen here
    // throws "The action 'RESET' was not handled by any navigator".
    if (plan.goReset) {
      const routes = rule.resetTo
        ? [{ name: rule.resetTo }, { name: target, params: plan.params }]
        : [{ name: target, params: plan.params }];
      if (__DEV__) console.log('[Test] rule.reset stack=' + routes.map((r) => r.name).join(' > '));
      plan.goReset(navigation, routes);
      return;
    }
    ruleReset(navigation, target, rule.resetTo, plan.params);
    return;
  }
  if (plan.resolveFlow && plan.flows?.includes(target)) {
    void plan
      .resolveFlow(target)
      .then((t) => goRuleTarget(navigation, plan, t))
      .catch((e: unknown) => console.warn('[gen] rule flow resolve failed', e));
    return;
  }
  goRuleTarget(navigation, plan, target);
}

/** First matching rule — rules can navigate AND/OR call another api. */
export function firstMatchingRule(
  rules: ResponseRule[],
  body: unknown,
  status: number,
): ResponseRule | null {
  for (const r of rules) {
    const actual = ruleActual(r, body, status);
    if (matchOp(actual, r.op, r.value)) {
      if (__DEV__)
        console.log(
          `[RULE ✓] ${r.source}${r.path ? '.' + r.path : ''} ${r.op} ${JSON.stringify(r.value)} ` +
            `(actual=${JSON.stringify(actual)}) → ${r.navigateTo || r.callBindingId || r.openModalId || 'no action'}`,
        );
      return r;
    }
  }
  /**
   * NO rule matched — which is silent, and looks exactly like a hang.
   *
   * A save that spins and then does nothing has usually landed here: the
   * response was fine, but every rule's condition disagreed with it, so no
   * navigation fired and nothing said why. Printing the rules alongside the
   * value they were tested against turns that into a one-line diagnosis.
   */
  if (__DEV__ && rules.length > 0)
    console.log(
      `[RULE ✗] none of ${rules.length} matched (status=${status}) :: ` +
        rules
          .map((r) => `${r.source}${r.path ? '.' + r.path : ''} ${r.op} ${JSON.stringify(r.value)}`)
          .join(' | '),
    );
  return null;
}

/** First matching rule's target screen name, or null. */
export function firstRuleTarget(
  rules: ResponseRule[],
  body: unknown,
  status: number,
): string | null {
  for (const r of rules) {
    if (matchOp(ruleActual(r, body, status), r.op, r.value)) return r.navigateTo;
  }
  return null;
}
